import {startFlowPlayback} from './flow-playback.js?v=speed-20261005';
import {buildAPI,apiMessages} from './api-model.js?v=api-review-20261007-r2';
import {apiGuides} from './api-teaching.js?v=api-review-20261007-r2';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function apiSurface(l){const guide=apiGuides[l.kind];return `<section class="mechanism-lab api-lab" aria-label="ห้องทดลอง API"><header><span>3D INTERACTIVE</span><h2>ใครส่งอะไร → ใครตัดสินใจ → ได้ผลอะไร</h2></header><p class="mechanism-disclaimer">คำนวณผลจากแบบจำลองใน Browser · ไม่เปิด API/server จริง ไม่ส่งข้อมูลออกนอกห้องทดลอง กล่อง Schema/Serializer/Service เป็นส่วนเชิงตรรกะ ไม่ใช่เครื่องจริงทุกกล่อง</p><section class="api-guide"><h3>เมื่อจบบทนี้ คุณจะทำได้</h3><p>${esc(guide.goal)}</p><details><summary>ข้อตกลงที่ใช้ในตัวอย่างนี้</summary><pre>${esc(guide.contract)}</pre></details><details><summary>8 รูปแบบต่างกันอย่างไร?</summary><p>REST เป็นแนวทางออกแบบระบบ; GraphQL เป็นภาษาและกลไกขอข้อมูล; gRPC เป็น framework เรียก method ระหว่างโปรแกรม; SOAP เป็น framework ข้อความ XML; WebSocket เป็นช่อง messages สองทาง; SSE ส่ง events ทางเดียว; Long Polling รอคำตอบแล้วขอใหม่; Webhook เป็น HTTP callback เมื่อเกิด event จึงใช้หลายแบบร่วมกันได้</p></details></section><div class="mechanism-inputs" role="group" aria-label="เลือกสถานการณ์ API">${l.cases.map((c,i)=>`<button class="button light" data-api-case="${i}" aria-pressed="${i===0}">${i+1}. ${esc(c)}</button>`).join('')}</div><form class="mechanism-inputs" data-api-form><label>สินค้า ID<select name="id"><option value="1">1 · สมุด ราคา 80</option><option value="99">99 · ไม่มีในข้อมูล</option></select></label><label>${esc(guide.input)}<input name="message" value="สมุดใหม่" maxlength="80" aria-label="ข้อความทดลอง API"></label><button class="button">ทดลองด้วยข้อมูลนี้</button></form><p class="mechanism-error" role="alert"></p><div class="mechanism-stage is-3d" data-api-stage></div><div class="mechanism-controls"><button data-api-control="previous">‹ ขั้นก่อน</button><button data-api-control="play">▶ เล่นขั้นตอน</button><button data-api-control="next">ขั้นถัดไป ›</button><label>ขั้นตอน<input aria-label="ขั้นตอน API" type="range" min="0" value="0"></label><button data-api-control="reset">เริ่มใหม่</button><button data-api-control="view">รีเซ็ตมุมมอง 3D</button></div><ol class="mechanism-step-list" aria-label="ขั้นตอนกลไก API"></ol><div class="mechanism-evidence" aria-live="polite"></div><div class="api-messages"><section><h3>${esc(guide.sent)}</h3><pre data-api-request>ยังไม่ส่ง</pre></section><section><h3>${esc(guide.received)}</h3><pre data-api-response>ยังไม่ได้รับคำตอบ</pre></section></div><section class="api-history" hidden><h3>คำตอบของรอบก่อนหน้า · ไม่ใช่คำตอบของคำขอที่กำลังรอ</h3><pre data-api-history></pre></section><p class="api-observation" role="status"></p><p class="api-inspector" hidden></p></section><section class="concept-lab"><p class="eyebrow">YOUR MISSION</p><h2>${esc(l.question)}</h2><p>ดูครบทุกขั้นของทั้ง 3 กรณี แล้วตอบจากผลที่สังเกต${l.kind==='rest'?' · POST ต้องทดลองชื่อใหม่และชื่อว่างด้วย':''}</p><div class="choices">${l.choices.map((c,i)=>`<button class="button light" data-api-answer="${i}">${esc(c)}</button>`).join('')}</div><button class="button light" id="hint">ขอคำใบ้</button><p class="feedback" id="feedback" role="status"></p>${l.additionalSource?`<p><a href="${l.additionalSource}" target="_blank" rel="noopener noreferrer">${l.kind==='rest'?'อ่าน REST architecture จาก Fielding':'อ่านนโยบาย Failed delivery ของ GitHub'} ↗</a></p>`:''}<p>แนวทางหัวข้อจาก <a href="https://www.instagram.com/p/Dd_26udtoec/" target="_blank" rel="noopener noreferrer">โพสต์ AlgoZen</a> · เรียบเรียงตัวอย่างและกลไกใหม่โดย TechAtlas; ข้อเท็จจริงใช้เอกสารหลักของแต่ละบท ไม่คัดลอกภาพหรือเสียง</p></section>`;}
export function initAPI(l,{complete}){
 const root=document.querySelector('.api-lab'),stage=root.querySelector('[data-api-stage]'),evidence=root.querySelector('.mechanism-evidence'),list=root.querySelector('.mechanism-step-list'),range=root.querySelector('[type=range]'),form=root.querySelector('form'),error=root.querySelector('.mechanism-error');
 let scenario=0,index=0,model=buildAPI(l),timer=null,scene=null,disposed=false,valid=true;const observed=new Set(),visited=new Map(),experiments=new Set();let submitted=false;
 function stop(){timer?.stop();timer=null;root.querySelector('[data-api-control=play]').textContent='▶ เล่นขั้นตอน';}
 function draw(){const f=model.steps[index];range.max=model.steps.length-1;range.value=index;scene?.showStep(index);stage.dataset.step=index;
  list.innerHTML=model.steps.map((s,i)=>`<li><button data-api-step="${i}" ${i===index?'aria-current="step"':''}>${i+1}. ${esc(s.title)}</button></li>`).join('');
  evidence.className='mechanism-evidence'+(f.status==='blocked'?' problem':'');evidence.innerHTML=`<p>${index+1} / ${model.steps.length} · ${esc(l.cases[scenario])}</p><h3>${esc(f.title)}</h3><p>${esc(f.detail)}</p><dl>${f.fields.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;
  const {request,response,round,history}=apiMessages(model,index);
  root.querySelector('[data-api-request]').textContent=(l.kind==='long-polling'?'รอบ '+round+'\n':'')+request;
  root.querySelector('.api-history').hidden=!history;root.querySelector('[data-api-history]').textContent=history;root.querySelector('[data-api-response]').textContent=response;
  root.querySelector('[data-api-control=previous]').disabled=index===0;root.querySelector('[data-api-control=next]').disabled=index===model.steps.length-1;
  if(!scene)stage.textContent=f.title+' · '+f.transfers.map(t=>`${t.from} → ${t.to}: ${t.message}`).join(' | ');
  if(valid){const key=scenario+':'+JSON.stringify(model.parameters),seen=visited.get(key)||new Set();seen.add(index);visited.set(key,seen);if(index===model.steps.length-1&&seen.size===model.steps.length){observed.add(scenario);if(l.kind==='rest'&&scenario===1&&submitted)experiments.add(model.parameters.message.trim()?model.parameters.message.trim()!=='สมุดใหม่'?'named':'default':'empty');}}
  root.dataset.ready=String(observed.size===3&&(l.kind!=='rest'||experiments.has('named')&&experiments.has('empty')));
  root.querySelector('.api-observation').textContent=l.cases.map((c,i)=>(observed.has(i)?'✓ ':'○ ')+(i+1)+'. '+c).join(' · ')+(l.kind==='rest'?' · POST ชื่อใหม่ '+(experiments.has('named')?'✓':'○')+' / ชื่อว่าง '+(experiments.has('empty')?'✓':'○'):'');
 }
 function rebuild(){stop();const ids=l.kind==='rest'?scenario!==1:['basics','graphql','grpc','soap'].includes(l.kind)&&scenario===0||l.kind==='graphql'&&scenario===1;const messages=l.kind==='rest'&&scenario===1||['websocket','sse'].includes(l.kind)&&scenario!==1&&(l.kind!=='sse'||scenario===0)||l.kind==='sse'&&scenario===1||l.kind==='long-polling'&&scenario===0||l.kind==='webhooks';for(const [name,show]of [['id',ids],['message',messages]]){form.elements[name].closest('label').hidden=!show;form.elements[name].disabled=!show;}form.querySelector('button').hidden=!(ids||messages);try{model=buildAPI(l,scenario,Object.fromEntries(new FormData(form)));valid=true;error.textContent='';index=0;scene?.setModel(model);draw();}catch(e){valid=false;error.textContent=e.message+' · ยังแสดงค่าที่ถูกต้องครั้งล่าสุด';}}
 root.querySelectorAll('[data-api-case]').forEach(b=>b.onclick=()=>{scenario=Number(b.dataset.apiCase);root.querySelectorAll('[data-api-case]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));form.reset();submitted=false;document.querySelector('#feedback').textContent='';rebuild();});
 form.onsubmit=e=>{e.preventDefault();submitted=true;document.querySelector('#feedback').textContent='';rebuild();};
 list.onclick=e=>{const b=e.target.closest('[data-api-step]');if(b){stop();index=Number(b.dataset.apiStep);draw();}};
 range.oninput=()=>{stop();index=Number(range.value);draw();};
 root.querySelectorAll('[data-api-control]').forEach(b=>b.onclick=()=>{const action=b.dataset.apiControl;if(action==='view'){scene?.resetView();return;}if(action==='play'){if(timer){stop();return;}if(index===model.steps.length-1)index=0;b.textContent='❚❚ หยุด';draw();timer=startFlowPlayback({scene:()=>scene,advance:()=>{index++;draw();},atEnd:()=>index===model.steps.length-1,onEnd:stop,connected:()=>!disposed&&root.isConnected});return;}stop();index=action==='reset'?0:Math.max(0,Math.min(model.steps.length-1,index+(action==='next'?1:-1)));draw();if(action==='reset')scene?.replay?.();});
 document.querySelectorAll('[data-api-answer]').forEach(b=>b.onclick=()=>{const f=document.querySelector('#feedback'),ready=observed.size===3&&valid&&(l.kind!=='rest'||experiments.has('named')&&experiments.has('empty')),pass=ready&&Number(b.dataset.apiAnswer)===l.answer;f.className='feedback'+(pass?'':' bad');f.textContent=!ready?'ดูครบทุกขั้นของทั้ง 3 กรณีก่อนตอบ'+(l.kind==='rest'?' และทดลอง POST ชื่อใหม่กับชื่อว่างให้ครบทุกขั้นทั้งสองครั้ง':''):(pass?'✓ ผ่านภารกิจ — ':'ลองอีกครั้ง — ')+l.reason;if(pass)complete(l.id);});
 stage.addEventListener('mechanism-pick',e=>{const n=model.nodes.find(n=>n.id===e.detail),box=root.querySelector('.api-inspector');if(n){box.hidden=false;box.textContent=n.name+' · '+(model.steps[index].nodeUpdates[n.id]||n.address)+(n.logical?' · ส่วนเชิงตรรกะในโปรแกรม ไม่จำเป็นต้องเป็นเครื่องอีกเครื่อง':' · ผู้เริ่มคำขอในตัวอย่าง');}});
 rebuild();import('./network-mechanism-scene.js?v=api-review-20261007-r2').then(({mountScene})=>{if(disposed)return;stage.replaceChildren();try{scene=mountScene(stage,{lesson:l,initialModel:model});stage.classList.add('has-webgl');draw();}catch{scene=null;error.textContent='3D ไม่พร้อม: ยังดูขั้นตอน คำขอ และคำตอบแบบข้อความได้';draw();}}).catch(()=>{error.textContent='โหลด 3D ไม่ได้: ใช้หลักฐานข้อความด้านล่างแทน';});
 return {dispose(){disposed=true;stop();scene?.dispose();}};
}
